files.content:
:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --text: #cdd6f4;
  --accent: #89b4fa;
  --accent-hover: #b4c6f0;
  --bar-hunger: #f38ba8;
  --bar-happiness: #a6e3a1;
  --bar-energy: #f9e2af;
  --shadow: rgba(0,0,0,0.3);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  font-size: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 24px var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--accent);
}

.pet-container {
  width: 120px;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pet {
  width: 80px;
  height: 80px;
  background: var(--accent);
  border-radius: 12px;
  position: relative;
  image-rendering: pixelated;
  box-shadow: 0 0 0 4px var(--accent-hover);
  transition: transform 0.2s ease;
}

.pet:hover {
  transform: scale(1.05);
}

.pet-eye {
  position: absolute;
  width: 12px;
  height: 12px;
  background: var(--bg);
  border-radius: 50%;
  top: 20px;
}

.pet-eye.left { left: 18px; }
.pet-eye.right { right: 18px; }

.pet-mouth {
  position: absolute;
  width: 24px;
  height: 8px;
  background: var(--bg);
  border-radius: 0 0 12px 12px;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--accent-hover);
  text-align: center;
  min-height: 1.5em;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  width: 80px;
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text);
  flex-shrink: 0;
}

.bar-bg {
  flex: 1;
  height: 16px;
  background: var(--bg);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: var(--bar-hunger); }
.bar-fill.happiness { background: var(--bar-happiness); }
.bar-fill.energy { background: var(--bar-energy); }

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: var(--bg);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.95);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  .stat-label {
    width: 60px;
    font-size: 0.75rem;
  }
  button {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

const state = {
  hunger: 100,
  happiness: 100,
  energy: 100
};

const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  let mood = "I'm feeling great!";
  if (state.hunger < 30) mood = "I'm hungry...";
  else if (state.energy < 30) mood = "I'm sleepy...";
  else if (state.happiness < 30) mood = "I'm bored...";
  else if (state.hunger < 60 || state.happiness < 60 || state.energy < 60) mood = "I'm okay.";

  moodEl.textContent = mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
